+    // ----- Navigate and wait for network idle -----
+    console.log(`📄 Navigating to ${opts.url}...`);
+    try {
+      await page.goto(opts.url!, {
+        waitUntil: 'networkidle0',
+        timeout: 10000,
+      });
+    } catch {
